<template>
  <section class="svn-plan-editor" aria-label="创建迁移计划">
    <el-skeleton v-if="initializing" :rows="10" animated />
    <template v-else>
      <el-button link class="back-link" :disabled="saving" @click="emit('back')"><el-icon><ArrowLeft /></el-icon>SVN 迁移 / {{ form.id?'编辑迁移计划':'创建迁移计划' }}</el-button>
      <header><h2>选择迁移目标</h2><p>已选择 {{ form.repositories.length }} 个 SVN 项目，指定它们在 Gitea 中的位置。</p></header>
      <SvnSteps :active="1" />
      <el-alert v-if="error" :title="error" type="error" show-icon :closable="false" />
      <el-empty v-if="!form.repositories.length" description="尚未选择项目，请返回来源页面选择"><el-button @click="emit('back')">选择项目</el-button></el-empty>
      <template v-else>
        <div class="target-layout">
          <section class="target-panel"><h3>迁移计划配置</h3>
            <el-form label-position="left" label-width="144px" @submit.prevent="save">
              <el-form-item label="计划名称" required><el-input v-model="form.name" aria-label="计划名称" maxlength="200" /></el-form-item>
              <el-form-item label="目标 Gitea 实例" required><el-select v-model="form.server_id" placeholder="选择已登记的 Gitea 实例" aria-label="目标 Gitea 实例"><el-option v-for="target in targets" :key="target.id" :value="target.id" :label="target.name" /></el-select></el-form-item>
              <el-form-item label="目标群组" required><div class="group-field"><el-select v-model="groupId" filterable :disabled="!form.server_id" :loading="loadingGroups" placeholder="请选择目标群组" aria-label="目标群组"><el-option v-for="group in availableGroups" :key="group.id" :value="group.id" :label="group.name+' · '+group.full_path" :disabled="!group.selectable" /></el-select><el-button :disabled="!form.server_id" @click="picker=true">选择群组</el-button></div><p class="field-note">请选择有创建仓库权限的群组。</p><el-button link type="primary" :disabled="!form.server_id" @click="openCreate"><el-icon><CirclePlus /></el-icon>新建群组</el-button></el-form-item>
              <el-form-item label="目标路径"><div class="target-prefix">{{ selectedGroup ? selectedGroup.full_path+'/' : '选择群组后显示' }}</div></el-form-item>
            </el-form>
            <el-alert v-if="groupError" :title="groupError" type="error" :closable="false" show-icon />
            <div class="permission-note"><el-icon><InfoFilled /></el-icon><span>沿用所选群组的权限，预检将检查建库权限与同名冲突。</span></div>
          </section>
          <section class="target-panel preview-panel"><h3>迁移结果预览</h3>
            <div class="destination-summary"><el-icon><Document /></el-icon><div>将创建以下 {{ form.repositories.length }} 个仓库到指定群组：<strong>{{ selectedTarget?.name || '请选择目标实例' }} / {{ selectedGroup ? selectedGroup.name+' · '+selectedGroup.full_path : '请选择目标群组' }}</strong></div></div>
            <div v-for="(row,index) in form.repositories" :key="row.id" class="destination-row"><el-icon class="folder-icon"><FolderOpened /></el-icon><strong class="source-name">{{ sourceName(row) }}</strong><el-icon class="path-arrow"><Right /></el-icon><span class="destination-path">{{ selectedGroup ? selectedGroup.full_path+'/'+row.name : '请选择目标群组' }}</span><div class="path-status" :class="pathRows[index]?.available?'is-available':pathRows[index]?'is-conflict':''"><span><el-icon><CircleCheckFilled v-if="pathRows[index]?.available"/><WarningFilled v-else-if="pathRows[index]"/><Loading v-else-if="checkingPaths"/><Clock v-else/></el-icon>{{ pathRows[index]?.message || (checkingPaths?'检查路径中':'待检查') }}</span><small>新建私有仓库</small></div></div>
            <el-alert v-if="pathError" :title="pathError" type="error" show-icon :closable="false" />
            <div class="complete-note"><el-icon><CircleCheckFilled /></el-icon>项目内容与目录结构保持完整。</div>
          </section>
        </div>
        <details class="advanced-settings"><summary>更多迁移设置</summary>
          <h4>仓库名称与迁移顺序</h4><div v-for="(row,index) in form.repositories" :key="row.id" class="repository-edit"><span>{{ sourceName(row) }}</span><el-input v-model="row.name" :aria-label="'目标仓库名 '+sourceName(row)"/><div class="button-group"><el-button size="small" :disabled="index===0" @click="move(index,-1)">上移</el-button><el-button size="small" :disabled="index===form.repositories.length-1" @click="move(index,1)">下移</el-button><el-button size="small" type="danger" link @click="exclude(index)">排除</el-button></div></div>
          <p>作者映射可留空，系统保留 SVN 署名；跨来源同名作者不会自动合并。</p><label for="svn-plan-authors">作者 CSV：source_id,svn_user,name,email</label><el-input id="svn-plan-authors" v-model="authorsCsv" type="textarea" :rows="4" />
          <label for="svn-target-ca">目标 Gitea CA 证书（可选）</label><el-input id="svn-target-ca" v-model="form.target_ca_pem" type="textarea" :rows="3" />
        </details>
        <footer class="target-footer"><el-button :disabled="saving" @click="emit('back')"><el-icon><ArrowLeft /></el-icon>上一步</el-button><div><span>预检通过后，再确认并执行迁移。</span><el-button type="primary" :loading="saving" :disabled="!canSave" @click="save">保存计划并预检<el-icon><ArrowRight /></el-icon></el-button></div></footer>
      </template>
      <el-dialog v-model="picker" title="选择目标群组" width="min(700px,94vw)" destroy-on-close><p>选择这 {{ form.repositories.length }} 个项目在 Gitea 中的归属位置。</p><el-alert v-if="groupError" :title="groupError" type="error" show-icon :closable="false"/><el-tree node-key="id" :key="form.server_id" lazy :load="loadTree" :props="{label:'name',isLeaf:'leaf'}" highlight-current :current-node-key="groupId"><template #default="{data}"><div class="group-tree-row"><el-icon><FolderOpened /></el-icon><span>{{ data.name }}<small>{{ data.full_path }}</small></span><el-tag :type="data.selectable?'success':'info'">{{ data.selectable?'可创建仓库':'不可选择' }}</el-tag><el-button size="small" :disabled="!data.selectable" :aria-label="'选择群组 '+data.full_path" @click.stop="chooseGroup(data)">选择</el-button></div></template></el-tree><template #footer><el-button @click="picker=false">关闭</el-button></template></el-dialog>
      <el-dialog v-model="creating" title="新建群组" width="min(560px,94vw)"><el-form label-position="top"><el-form-item label="群组名称" required><el-input v-model="newGroup.name" aria-label="新群组名称" maxlength="100" /></el-form-item><el-form-item label="群组路径" required><el-input v-model="newGroup.path" aria-label="新群组路径" placeholder="例如 firmware" maxlength="80" /></el-form-item><el-form-item label="父群组"><el-select v-model="newGroup.parent_id" aria-label="父群组"><el-option :value="0" label="顶级群组"/><el-option v-for="group in availableGroups.filter(g=>g.can_create_group)" :key="group.id" :value="group.id" :label="group.name+' · '+group.full_path"/></el-select></el-form-item></el-form><p>创建私有群组后返回当前计划，不会立即迁移项目。</p><el-alert v-if="createError" :title="createError" type="error" :closable="false" show-icon/><template #footer><el-button @click="creating=false">取消</el-button><el-button type="primary" :loading="creatingBusy" :disabled="createUncertain||!newGroup.name.trim()||!newGroup.path.trim()" @click="createGroup">创建并选择</el-button></template></el-dialog>
    </template>
  </section>
</template>
<script setup>
import { computed, onMounted, onBeforeUnmount, ref, watch } from 'vue'
import { ArrowLeft, ArrowRight, Right, CirclePlus, FolderOpened, Document, InfoFilled, CircleCheckFilled, WarningFilled, Loading, Clock } from '@element-plus/icons-vue'
import { api } from '../api'
import SvnSteps from './SvnSteps.vue'
const props=defineProps({ repositories:{type:Array,default:()=>[]}, selectedIds:{type:Array,default:()=>[]}, targets:{type:Array,default:()=>[]}, planId:{type:Number,default:null} })
const emit=defineEmits(['back','saved'])
const form=ref({name:'SVN 内容迁移',server_id:null,repositories:[],target_ca_pem:'',excluded:[]}),authorsCsv=ref('source_id,svn_user,name,email\n')
const initializing=ref(true),saving=ref(false),error=ref(''),groupId=ref(null),groups=ref([]),loadingGroups=ref(false),groupError=ref(''),picker=ref(false)
const checkingPaths=ref(false),pathRows=ref([]),pathError=ref(''),creating=ref(false),creatingBusy=ref(false),createError=ref(''),createUncertain=ref(false),newGroup=ref({name:'',path:'',parent_id:0})
let groupGeneration=0,pathGeneration=0,pathTimer,disposed=false
const availableGroups=computed(()=>[...groups.value].sort((a,b)=>a.full_path.localeCompare(b.full_path)))
const selectedGroup=computed(()=>groups.value.find(g=>g.id===groupId.value))
const selectedTarget=computed(()=>props.targets.find(t=>t.id===form.value.server_id))
const canSave=computed(()=>form.value.name.trim()&&form.value.repositories.length&&selectedGroup.value?.selectable&&!checkingPaths.value&&!pathError.value&&pathRows.value.length===form.value.repositories.length&&pathRows.value.every(row=>row.available)&&!saving.value)
const sourceName=row=>props.repositories.find(r=>r.id===row.id)?.name || row.name
function mergeGroups(rows){groups.value=[...new Map([...groups.value,...rows].map(group=>[group.id,group])).values()]}
async function fetchGroups(parent_id=0){
 const version=groupGeneration,server=form.value.server_id,all=[];let after_id=0
 do{const {data}=await api.post(`/svn-migrations/targets/${server}/groups/query`,{parent_id,after_id,target_ca_pem:form.value.target_ca_pem});if(version!==groupGeneration||disposed)return [];all.push(...data.groups);if(all.length>2000)throw Error('本层群组超过 2000 个，请使用更具体的父群组');after_id=data.next_id}while(after_id)
 mergeGroups(all);return all
}
async function loadGroups(){if(!form.value.server_id)return;const version=groupGeneration;loadingGroups.value=true;groupError.value='';try{await fetchGroups()}catch(e){if(version===groupGeneration)groupError.value=e.response?.data?.error||e.message||'无法读取目标群组'}finally{if(version===groupGeneration)loadingGroups.value=false}}
async function loadTree(node,resolve){try{resolve(await fetchGroups(node.level===0?0:node.data.id))}catch(e){groupError.value=e.response?.data?.error||'无法读取子群组';resolve([])}}
function chooseGroup(group){if(group.selectable){groupId.value=group.id;picker.value=false}}
function schedulePaths(){pathGeneration++;clearTimeout(pathTimer);pathRows.value=[];pathError.value='';checkingPaths.value=false;if(!initializing.value&&form.value.server_id&&groupId.value&&form.value.repositories.length){checkingPaths.value=true;pathTimer=setTimeout(checkPaths,300)}}
async function checkPaths(){
 const version=pathGeneration,names=form.value.repositories.map(row=>row.name)
 if(names.some(name=>!(/^[A-Za-z0-9][A-Za-z0-9_.-]*$/).test(name)||name.length>120||name.toLowerCase().endsWith('.git'))){pathError.value='目标仓库名只能使用英文、数字、点、短横线或下划线，且不能以 .git 结尾';checkingPaths.value=false;return}
 try{const {data}=await api.post(`/svn-migrations/targets/${form.value.server_id}/paths`,{group_id:groupId.value,names,target_ca_pem:form.value.target_ca_pem});if(version===pathGeneration&&!disposed){mergeGroups([data.group]);pathRows.value=data.repositories}}
 catch(e){if(version===pathGeneration&&!disposed)pathError.value=e.response?.data?.error||'无法检查目标路径，请重试'}finally{if(version===pathGeneration&&!disposed)checkingPaths.value=false}
}
watch(()=>form.value.server_id,()=>{if(initializing.value)return;groupGeneration++;groupId.value=null;groups.value=[];creating.value=false;loadGroups();schedulePaths()},{flush:'sync'})
watch(()=>form.value.target_ca_pem,()=>{if(!initializing.value){groupGeneration++;groups.value=[];loadGroups()} })
watch(()=>[groupId.value,form.value.repositories.map(row=>row.name).join('\n'),form.value.target_ca_pem],schedulePaths)
function move(index,delta){const rows=form.value.repositories;[rows[index],rows[index+delta]]=[rows[index+delta],rows[index]]}
function exclude(index){const [row]=form.value.repositories.splice(index,1);form.value.excluded.push({id:row.id,name:row.name,reason:'管理员在计划中明确排除'})}
function openCreate(){newGroup.value={name:'',path:'',parent_id:0};createError.value='';createUncertain.value=false;creating.value=true}
async function createGroup(){if(creatingBusy.value||createUncertain.value)return;creatingBusy.value=true;createError.value='';const generation=groupGeneration,server=form.value.server_id;try{const {data}=await api.post(`/svn-migrations/targets/${form.value.server_id}/groups`,{...newGroup.value,target_ca_pem:form.value.target_ca_pem});if(disposed||generation!==groupGeneration||server!==form.value.server_id)return;mergeGroups([data]);groupId.value=data.id;creating.value=false}catch(e){createUncertain.value=e.response?.data?.code==='uncertain'||!e.response;createError.value=createUncertain.value?'创建结果未能确认，请关闭窗口并刷新群组列表核对，不要重复创建。':e.response?.data?.error||'创建群组失败'}finally{creatingBusy.value=false}}
async function save(){if(!canSave.value)return;saving.value=true;error.value='';try{const payload={...form.value,target_group:{id:groupId.value},authors:authorsCsv.value.trim()==='source_id,svn_user,name,email'?[]:authorsCsv.value};const {data}=await api[form.value.id?'put':'post']('/svn-migrations/plans'+(form.value.id?'/'+form.value.id:''),payload);form.value.id=data.id;form.value.version=data.version;const result=await api.post(`/svn-migrations/plans/${data.id}/preflight`);if(!disposed)emit('saved',result.data)}catch(e){error.value=e.response?.data?.error||'保存或启动预检失败，请重试'}finally{saving.value=false}}
onMounted(async()=>{try{if(props.planId){const {data}=await api.get(`/svn-migrations/plans/${props.planId}`);form.value={...data.config,id:data.id,version:data.version,name:data.name,server_id:data.server_id};groupId.value=data.config.target_group?.id||null;authorsCsv.value='source_id,svn_user,name,email\n'+data.config.authors.map(row=>[row.source_id,row.svn_user,row.name,row.email].map(value=>'"'+String(value).replaceAll('"','""')+'"').join(',')).join('\n')}else form.value.repositories=props.repositories.filter(row=>props.selectedIds.includes(row.id)).map(row=>({id:row.id,name:row.name}));await loadGroups()}catch(e){error.value=e.response?.data?.error||'无法读取迁移计划'}finally{initializing.value=false;schedulePaths()}})
onBeforeUnmount(()=>{disposed=true;groupGeneration++;pathGeneration++;clearTimeout(pathTimer)})
</script>
<style scoped>
