e9f4;padding:24px 0;min-width:0;font-size:15px}.folder-icon{color:#1684ff;font-size:25px}.source-name,.destination-path{overflow-wrap:anywhere;line-height:1.7}.source-name{font-weight:500}.path-arrow{color:#7d93b4}.path-status{grid-column:4;display:grid;gap:6px;color:#7b8ca6;font-size:13px}.path-status>span{display:flex;align-items:center;gap:6px}.path-status small{font-size:12px;color:#7b8ca6}.is-available{color:#168449}.is-conflict{color:#d33f35}.complete-note{display:flex;gap:12px;align-items:center;color:#087e40;background:#eafbf1;border:1px solid #c6efda;border-radius:7px;padding:16px;margin-top:25px;font-weight:600}.complete-note .el-icon{font-size:24px;flex:0 0 24px}.advanced-settings{font-size:14px;color:#536783}.advanced-settings summary{cursor:pointer;padding:12px 0}.advanced-settings h4{margin:15px 0}.advanced-settings label{display:block;margin:18px 0 8px}.repository-edit{display:grid;grid-template-columns:minmax(100px,1fr) minmax(160px,1fr) auto;gap:14px;align-items:center;margin:12px 0}.repository-edit>span{overflow-wrap:anywhere}.target-footer{display:flex;justify-content:space-between;align-items:center;gap:18px;flex-wrap:wrap;padding:20px;border:1px solid #d4e5f6;border-radius:10px;background:rgba(255,255,255,.9)}.target-footer>div{display:flex;align-items:center;gap:22px;flex-wrap:wrap;min-width:0}.target-footer>div>span{font-size:14px;color:#657c9b}.target-footer .el-button{min-height:44px}.target-footer .el-icon{margin:0 6px}.group-tree-row{display:flex;align-items:center;gap:12px;min-width:0;flex:1;padding:10px 0}.group-tree-row>span{flex:1;min-width:0;overflow-wrap:anywhere}.group-tree-row small{display:block;font-size:12px;color:#7588a4;margin-top:4px}.group-tree-row>.el-icon{color:#1479f6}.svn-plan-editor :deep(.el-tree-node__content){height:auto;min-height:56px}.svn-plan-editor :deep(.el-input__wrapper){min-height:38px;border-radius:6px;font-size:15px}.svn-plan-editor :deep(.el-select__wrapper){min-height:42px;border-radius:6px;font-size:15px}@media(max-width:1100px){.target-panel{padding:20px}.target-panel :deep(.el-form-item){display:block}.target-panel :deep(.el-form-item__label){display:block;text-align:left;margin-bottom:7px}.destination-row{grid-template-columns:24px minmax(0,1fr) 18px}.destination-path{grid-column:2/-1}.path-status{grid-column:2/-1}}@media(max-width:800px){.target-layout{grid-template-columns:minmax(0,1fr)}.target-panel{min-height:0}.target-panel h3{margin-bottom:22px}.target-footer>div{width:100%;justify-content:space-between}.repository-edit{grid-template-columns:minmax(0,1fr)}.group-field{flex-wrap:wrap}.group-field .el-select{min-width:180px}.svn-plan-editor header h2{font-size:28px}}
</style>
